import {rule} from './design-rules.mjs?v=0.8.14';
const n=x=>Number.isFinite(x)?new Intl.NumberFormat('fr-CA',{maximumFractionDigits:5}).format(x):'valeur à compléter';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Explanations mirror the consuming rules; they never change simulation state.
export function designContext(id,world,values={}) {
 const r=key=>n(values[key]??rule(world,key)),v=r(id),g=key=>r('groups.'+key);
 const result=(formula,context,example='')=>({formula,context,example});
 if(id.startsWith('groups.attachment.'))return result(
  `attachement = borner(coordination + ${g('attachment.affinity')} × (affinité − 50) + ${g('attachment.style')} × (style − 50) + ${g('attachment.chemistry')} × (chimie − 50) + ${g('attachment.reputation')} × réputation − ${g('attachment.tension')} × tension, 0, 100)`,
  'Affinité : moyenne des liens du musicien vers les autres membres, chacun borné entre 0 et 100. Chimie et tension : moyennes avec ces membres. Style : pourcentage de chansons actives de son genre, sinon des fondateurs. Coordination = progression du groupe. Les composantes centrées sur 50 peuvent enlever des points.');
 if(id.startsWith('needs.'))return result(`besoin suivant = borner(besoin − ${v} × usure globale × modulation, 0, 100)`,
  'À chaque minute de jeu, même en déplacement. Modulation énergie = 0 pendant le sommeil, sinon 1. Connexion sociale = 0,5 pour un solitaire, sinon 1 + extraversion / 200. Autres besoins = 1. Les gains de l’action s’appliquent ensuite séparément.',
  `En 60 minutes, avec usure globale = 1 et modulation = 1 : perte brute de ${n(60*(values[id]??rule(world,id)))} points, avant gains et limites.`);
 if(id.startsWith('effects.')){const jam=id.startsWith('effects.jam.');return result(`besoin suivant = borner(besoin + ${v}${jam?'':' × modulation'}, 0, 100)`,
  jam?'À chaque minute de jam actif. Le gain social exige au moins deux participants présents. Les autres effets ne reçoivent pas de modulation perfectionniste dans ce parcours. L’usure normale reste active.':'À chaque minute active sur place, hors trajet et attente de partenaires. Modulation = 0,8 pour l’expression d’un perfectionniste, sinon 1. Une valeur négative est un coût. L’usure normale reste active.',
  `Sur 10 minutes actives, sans modulation ni limites : ${n(10*(values[id]??rule(world,id)))} points. Ce total brut exclut l’usure.`);}
 const key=id.replace('groups.','');
 if(['affinity','love','tension'].includes(key))return result(`admissible = (min(affinité A→B, B→A) ≥ ${g('affinity')} OU min(amour A→B, B→A) ≥ ${g('love')}) ET max(tension A→B, B→A) < ${g('tension')}`,'Ce filtre vérifie les deux directions du lien. Les délais, appartenances et décisions d’acceptation restent des conditions supplémentaires ; être admissible ne crée pas automatiquement un groupe.');
 if(['proposal','recruitmentProposal'].includes(key))return result(`chance = ${v} / (1 + autres groupes²) × max(0,05 ; 1 − meilleur attachement / 100)`, 'Lors d’une proposition automatique admissible. Les autres groupes sont ceux de l’initiateur, en excluant le groupe qui recrute. Un tirage uniforme entre 0 et 1 doit être inférieur à cette chance. L’acceptation du destinataire vient ensuite.',`Sans autre groupe : ${n(100*(values[id]??rule(world,id)))} %. Avec un autre groupe et 50 d’attachement : ${n(25*(values[id]??rule(world,id)))} %.`);
 if(key==='recruitmentWeight')return result(`poids recrutement = ${v} × (1 + attachement candidat / 25) ; poids création = 1 + 18 / 25`, 'Parmi les options admissibles : probabilité de choisir une option = son poids / somme des poids. Le tirage de proposition est ensuite effectué séparément. Un poids de zéro retire les recrutements de ce choix.');
 if(['membershipDelay','recruitmentDelay','pairDelay'].includes(key))return result(`temps actuel − dernière ${key==='pairDelay'?'proposition à cette paire':'formation ou adhésion'} ≥ ${v} min`, 'Condition préalable à une nouvelle proposition. Les dates passées ne changent pas quand ce paramètre est modifié.');
 if(['rehearsalChance','fragileRehearsalChance','fragileCoordination'].includes(key))return result(`chance d’appel = coordination < ${g('fragileCoordination')} ? ${g('fragileRehearsalChance')} : ${g('rehearsalChance')}`,`À chaque décision de pratique (intervalle ${g('decisionMinutes')} min), si le répertoire contient une chanson active. Chaque invité décide ensuite de venir ; un appel ne garantit pas une pratique collective.`);
 if(key==='decisionMinutes')return result(`prochaine décision = temps actuel + ${v} min`, 'Deux horloges distinctes : adoption d’une chanson et appel de pratique. À l’initialisation du groupe, premier délai = plancher(aléatoire × intervalle) + 1. Les échéances déjà programmées sont conservées.');
 if(key==='invitationMinutes')return result(`expiration = création de l’appel + ${v} min`, 'Durée des nouveaux appels. Une invitation peut expirer sans que le musicien l’exécute. Les invitations déjà créées gardent leur expiration.');
 if(key==='waitMinutes')return result(`fin d’attente si temps actuel − première arrivée ≥ ${v} min`, 'Si les conditions de départ de la pratique ne sont pas réunies, l’appel se ferme à ce délai ou à son expiration. Le paramètre intervient aussi pour éviter une pratique qui empiéterait sur un déplacement vers un show.');
 if(['departureMinutes','departureGrace'].includes(key))return result(`prochaine évaluation = ${key==='departureGrace'?'date d’adhésion':'temps actuel'} + ${v} min`, key==='departureGrace'?'Délai initial des nouveaux membres. Ne déplace pas les évaluations des membres déjà présents.':'Lorsqu’une évaluation arrive à échéance, la prochaine est programmée, même si un spectacle proche protège le membre du départ.');
 if(['lowAttachment','departureChance','alternativeGap','alternativeChance'].includes(key))return result(`risque = min(0,30 ; (attachement < ${g('lowAttachment')} ? ${g('departureChance')} : 0) + (autre attachement − attachement ≥ ${g('alternativeGap')} ? ${g('alternativeChance')} : 0))`, 'À chaque évaluation admissible, après le délai initial et hors protection de spectacle. L’alternative est un autre groupe déjà rejoint. Les deux risques peuvent se cumuler, mais le total ne dépasse pas 30 %.');
 if(key==='nearShow')return result(`protégé si date du show − temps actuel ≤ ${v} min`, 'Le musicien doit figurer dans la formation d’un show du groupe, réservé, en rassemblement ou en cours. Cette protection évite la décision de départ du groupe.');
 if(key==='arrivalMargin')return result(`départ = date du show − durée du trajet − ${v} min`, 'La durée vient du trajet calculé. Cette marge avance l’heure de départ ; elle ne téléporte pas le personnage et ne modifie pas la date du spectacle.');
 if(['absenceThreshold','absenceSlope'].includes(key))return result(`risque d’absence = min(0,20 ; max(0 ; déchéance − ${g('absenceThreshold')}) × ${g('absenceSlope')})`, 'Tirage d’absence pour déchéance au départ vers le show. Le résultat est mémorisé pour ce spectacle, sans refaire un tirage chaque minute. À la valeur exacte du seuil, le risque est nul.');
 if(key==='positiveAffinity')return result(`gain = (${v} + bonus chimie) × évolution globale des liens`, 'Après un échange favorable, dans chaque direction. Bonus chimie = max(0 ; chimie musicale − 50) / 100 pour un échange musical, sinon 0. Affinité finale bornée entre −100 et 100.');
 if(key==='negativeAffinity')return result(`perte = ${v} × évolution globale des liens`, 'Après un échange défavorable, dans chaque direction. Affinité finale bornée entre −100 et 100. La tension et les émotions ont leurs propres changements.');
 if(key==='tensionErosion')return result(`perte = ${v} × (tension − 20), si tension ≥ 30`, 'Chaque minute, après le refroidissement de la tension. Affinité finale bornée entre −100 et 100. Cette érosion ne reçoit pas le multiplicateur global des liens.');
 const relation=id.replace('relations.','');
 if(relation==='romanticStart')return result(`chance = ${v} × romance globale × max(0 ; 1 + effet des traits)`, 'Après une discussion favorable entre adultes, dans chaque direction où l’amour est encore nul, et si la romance globale est positive. Un succès initialise le lien au seuil d’avance.');
 if(relation==='advanceThreshold')return result(`avance admissible si amour de l’initiateur ≥ ${v}`, 'Les autres conditions sociales restent actives. Ce seuil sert aussi de niveau initial à un nouveau lien amoureux et de condition au gain réciproque de +4 lors d’une avance favorable.');
 if(['coupleThreshold','coupleChance'].includes(relation))return result(`si amour A→B ≥ ${r('relations.coupleThreshold')} ET amour B→A ≥ ${r('relations.coupleThreshold')} : tirage < ${r('relations.coupleChance')}`, 'Toutes les 60 minutes de jeu, pour une paire qui n’est pas déjà en couple dans ses liens réciproques. Ce pourcentage est une chance par évaluation admissible, pas une proportion garantie de couples.');
 if(['breakupThreshold','breakupChance'].includes(relation))return result(`si min(amour A→B, B→A) < ${r('relations.breakupThreshold')} : tirage < ${r('relations.breakupChance')}`, 'Toutes les 60 minutes de jeu, pour un couple existant. Une seule direction sous le seuil suffit. Le seuil de rupture doit être inférieur ou égal au seuil de mise en couple.');
 throw Error('Contexte manquant : '+id);
}
export function designContextHTML(id,world,values){
 const c=designContext(id,world,values);
 return `<p class="design-formula"><strong>Formule · valeurs préparées</strong><code>${esc(c.formula)}</code></p><p>${esc(c.context)}</p>${c.example?`<p class="design-example"><strong>Exemple :</strong> ${esc(c.example)}</p>`:''}<small>borner(x, min, max) limite le résultat à cet intervalle. Le brouillon ne modifie le jeu qu’après application.</small>`;
}
